// CreateStockAsset is the resolver for the createStockAsset field.
func (r *mutationResolver) CreateStockAsset(ctx context.Context, input gqlModel.CreateStockInput) (*gqlModel.Stock, error) {
	var asset *model.Asset
	var err error
	userID, _ := getUserIDFromContext(ctx)
	ownerPtr := (*string)(nil)
	if strings.TrimSpace(userID) != "" {
		ownerPtr = &userID
	}

	quoteCurrency := model.Currency(strings.ToUpper(strings.TrimSpace(input.QuoteCurrency)))
	if !quoteCurrency.IsValid() {
		return nil, fmt.Errorf("invalid quote currency: %s", input.QuoteCurrency)
	}

	metadata, marshalErr := json.Marshal(map[string]string{
		"currency": quoteCurrency.String(),
	})
	if marshalErr != nil {
		return nil, fmt.Errorf("failed to marshal stock metadata: %w", marshalErr)
	}

	err = r.UOW.Do(ctx, func(uow repository.IUnitOfWork) error {
		normalizedTicker := strings.ToUpper(strings.TrimSpace(input.Ticker))
		var linkedInstrumentID *string
		rows, searchErr := uow.Instrument().Search(ctx, normalizedTicker, repository.InstrumentSearchFilter{
			AssetTypes: []model.InstrumentAssetType{
				model.InstrumentAssetTypeStock,
				model.InstrumentAssetTypeETF,
				model.InstrumentAssetTypeFund,
			},
			OwnerUserID: ownerPtr,
			Limit:       5,
		})
		if searchErr != nil {
			return fmt.Errorf("failed to search instrument: %w", searchErr)
		}
		for _, row := range rows {
			if strings.EqualFold(strings.TrimSpace(row.Instrument.Symbol), normalizedTicker) {
				instrumentID := row.Instrument.ID
				linkedInstrumentID = &instrumentID
				break
			}
		}
		if linkedInstrumentID == nil {
			now := time.Now().UTC()
			manualInstrument := &model.Instrument{
				Symbol:           normalizedTicker,
				NormalizedSymbol: normalizedTicker,
				Name:             strings.TrimSpace(input.Name),
				NormalizedName:   strings.ToLower(strings.TrimSpace(input.Name)),
				Exchange:         "MANUAL",
				AssetType:        model.InstrumentAssetTypeStock,
				Status:           model.InstrumentStatusUnknown,
				ProviderSource:   "manual",
				OwnerUserID:      ownerPtr,
				FirstSeenAt:      now,
			}
			if manualInstrument.NormalizedName == "" {
				manualInstrument.NormalizedName = strings.ToLower(normalizedTicker)
			}
			createdInstrument, createInstrumentErr := uow.Instrument().Upsert(ctx, manualInstrument)
			if createInstrumentErr != nil {
				return fmt.Errorf("failed to create manual instrument for ticker %s: %w", normalizedTicker, createInstrumentErr)
			}
			if createdInstrument != nil && strings.TrimSpace(createdInstrument.ID) != "" {
				instrumentID := strings.TrimSpace(createdInstrument.ID)
				linkedInstrumentID = &instrumentID

				_, _ = uow.InstrumentProviderMapping().Upsert(ctx, &model.InstrumentProviderMapping{
					InstrumentID:    instrumentID,
					Provider:        "YFINANCE",
					ProviderAssetID: normalizedTicker,
					ProviderSymbol:  &normalizedTicker,
					QuoteCurrency:   stringPtr(quoteCurrency.String()),
					MappingStatus:   model.InstrumentProviderMappingStatusVerified,
					LastVerifiedAt:  &now,
				})
			}
		}

		asset, err = uow.Asset().Create(ctx, &model.Asset{
			InstrumentID: linkedInstrumentID,
			Name:         input.Name,
			Symbol:       &input.Ticker,
			Type:         model.AssetTypeStock,
			IsTradeable:  true,
			Metadata:     metadata,
		})
		if err != nil {
			return err
		}

		_, err = uow.Stock().Create(ctx, &model.Stock{
			AssetID:     asset.ID,
			Ticker:      input.Ticker,
			Quantity:    input.Quantity,
			BuyingPrice: getFloat64(input.PurchasePrice),
		})
		return err
	})

	if err != nil {
		return nil, err
	}

	tags, _ := r.TagService.GetAssetTags(ctx, asset.ID)
	// We need to load the stock details for mapping
	stockDetails, _ := r.UOW.Stock().GetByID(ctx, asset.ID)

	result := mapStockToGQL(*asset, stockDetails, tags, nil, nil, nil)
	// Set fields that come from input but aren't persisted in the assets table
	result.CurrentValue = input.CurrentValue
	result.PurchaseDate = input.PurchaseDate
	result.PurchasePrice = input.PurchasePrice

	r.triggerAssetPriceRefresh(asset)

	return result, nil
}

// CreateCryptoAsset is the resolver for the createCryptoAsset field.
func (r *mutationResolver) CreateCryptoAsset(ctx context.Context, input gqlModel.CreateCryptoInput) (*gqlModel.Crypto, error) {
	var asset *model.Asset
	var err error

	quoteCurrency := model.Currency(strings.ToUpper(strings.TrimSpace(input.QuoteCurrency)))
	if !quoteCurrency.IsValid() {
		return nil, fmt.Errorf("invalid quote currency: %s", input.QuoteCurrency)
	}

	metadataPayload := map[string]interface{}{
		"currency": quoteCurrency.String(),
	}
	if input.PurchaseDate != nil {
		metadataPayload["purchase_date"] = input.PurchaseDate.UTC().Format(time.RFC3339)
	}
	if input.BlockchainNetwork != nil {
		metadataPayload["blockchain"] = *input.BlockchainNetwork
	}
	if input.WalletAddress != nil {
		metadataPayload["wallet_address"] = *input.WalletAddress
	}
	metadata, marshalErr := json.Marshal(metadataPayload)
	if marshalErr != nil {
		return nil, fmt.Errorf("failed to marshal crypto metadata: %w", marshalErr)
	}

	err = r.UOW.Do(ctx, func(uow repository.IUnitOfWork) error {
		// Manual create path is non-tradeable. Tradeable crypto must use addInstrumentToPortfolio.
		asset, err = uow.Asset().Create(ctx, &model.Asset{
			Name:        input.Name,
			Symbol:      &input.Name, // Use name as symbol if ticker not provided
			Type:        model.AssetTypeCrypto,
			IsTradeable: false,
			Metadata:    metadata,
		})
		if err != nil {
			return err
		}

		_, err = uow.Crypto().Create(ctx, &model.Crypto{
			AssetID:           asset.ID,
			Quantity:          input.Quantity,
			WalletAddress:     getStr(input.WalletAddress),
			BlockchainNetwork: getStr(input.BlockchainNetwork),
		})
		return err
	})

	if err != nil {
		return nil, err
	}

	tags, _ := r.TagService.GetAssetTags(ctx, asset.ID)
	cryptoDetails, _ := r.UOW.Crypto().GetByID(ctx, asset.ID)

	result := mapCryptoToGQL(*asset, cryptoDetails, tags, nil, nil, nil)
	// Set fields that come from input but aren't persisted in the assets table
	result.CurrentValue = input.CurrentValue
	result.PurchaseDate = input.PurchaseDate
	result.PurchasePrice = input.PurchasePrice

	return result, nil
}

