// Portfolio is the resolver for the portfolio field.
func (r *queryResolver) Portfolio(ctx context.Context, id string) (*gqlModel.Portfolio, error) {
	p, err := r.PortfolioService.GetByID(ctx, id)
	if err != nil {
		if errors.Is(err, repository.ErrNotFound) || errors.Is(err, service.ErrPortfolioNotFound) {
			return nil, nil
		}
		return nil, err
	}
	gqlP := mapPortfolioToGQL(*p)

	// Get user's display currency for analytics
	displayCurrency, err := r.Resolver.getDisplayCurrencyFromContext(ctx)
	if err != nil {
		displayCurrency = model.CurrencyUSD // Default to USD
	}

	analytics, err := r.PortfolioService.GetPortfolioAnalytics(ctx, p.ID, displayCurrency)
	if err == nil {
		gqlP.Analytics = mapPortfolioValuationToGQL(analytics)
	}

	gqlP.Assets = r.buildPortfolioAssets(ctx, p.ID)

	return gqlP, nil
}

// GetPortfoliosWithAnalytics is the resolver for the GetPortfoliosWithAnalytics field.
func (r *queryResolver) GetPortfoliosWithAnalytics(ctx context.Context, userID string) ([]*gqlModel.Portfolio, error) {
	portfolios, err := r.PortfolioService.GetPortfoliosByUser(ctx, userID, "sort_order")
	if err != nil {
		return nil, err
	}

	// Get user's display currency for analytics
	displayCurrency, err := r.Resolver.getDisplayCurrencyFromContext(ctx)
	if err != nil {
		displayCurrency = model.CurrencyUSD // Default to USD
	}

	res := make([]*gqlModel.Portfolio, len(portfolios))
	for i, p := range portfolios {
		gqlP := mapPortfolioToGQL(p)

		analytics, err := r.PortfolioService.GetPortfolioAnalytics(ctx, p.ID, displayCurrency)
		if err == nil {
			gqlP.Analytics = mapPortfolioValuationToGQL(analytics)
		}

		gqlP.Assets = r.buildPortfolioAssets(ctx, p.ID)

		res[i] = gqlP
	}
	return res, nil
}

