// Assets is the resolver for the assets field.
func (r *queryResolver) Assets(ctx context.Context, filter *gqlModel.AssetFilter, pagination *gqlModel.PaginationInput, orderBy *gqlModel.AssetOrder) ([]gqlModel.Asset, error) {
	serviceFilter := service.AssetFilter{}
	if filter != nil {
		if filter.AssetTypeID != nil {
			at := model.AssetType(*filter.AssetTypeID)
			serviceFilter.AssetType = &at
		}
		serviceFilter.SearchTerm = filter.NameContains
	}
	if pagination != nil {
		if pagination.Limit != nil {
			l := int(*pagination.Limit)
			serviceFilter.Limit = &l
		}
		if pagination.Offset != nil {
			o := int(*pagination.Offset)
			serviceFilter.Offset = &o
		}
	}

	assets, err := r.AssetService.ListAssets(ctx, serviceFilter)
	if err != nil {
		return nil, err
	}

	res := make([]gqlModel.Asset, len(assets))
	for i, a := range assets {
		tags, _ := r.TagService.GetAssetTags(ctx, a.ID)
		if a.Type == model.AssetTypeStock {
			stockDetails, _ := r.UOW.Stock().GetByID(ctx, a.ID)
			res[i] = mapStockToGQL(*a, stockDetails, tags, nil, nil, nil)
		} else if a.Type == model.AssetTypeCrypto {
			cryptoDetails, _ := r.UOW.Crypto().GetByID(ctx, a.ID)
			res[i] = mapCryptoToGQL(*a, cryptoDetails, tags, nil, nil, nil)
		} else if a.Type == model.AssetTypeFund {
			fundDetails, _ := r.UOW.Fund().GetByID(ctx, a.ID)
			res[i] = mapFundToGQL(*a, fundDetails, tags, nil, nil, nil)
		} else if a.Type == model.AssetTypeBankAccount {
			res[i] = mapBankAccountToGQL(*a, tags, nil, nil, nil)
		} else if a.Type == model.AssetTypeRealEstate {
			res[i] = mapRealEstateToGQL(*a, tags, nil, nil, nil)
		} else if a.Type == model.AssetTypeLifeInsurance {
			res[i] = mapLifeInsuranceToGQL(*a, tags, nil, nil, nil)
		} else if a.Type == model.AssetTypeWatch {
			res[i] = mapWatchToGQL(*a, tags, nil, nil, nil)
		} else if a.Type == model.AssetTypeLoan {
			res[i] = mapLoanToGQL(*a, tags, nil, nil, nil)
		} else {
			// Generic mapping if needed
			res[i] = mapStockToGQL(*a, nil, tags, nil, nil, nil) // Fallback
		}
	}
	return res, nil
}

